// Escolhe os clientes a avisar hoje. Ajuste as regras e o limite diário.
// Datas na planilha devem estar como AAAA-MM-DD. Células vazias nunca contam como zero.
const LIMITE_DIARIO = 30;
const DIAS_ANTES = 7;
const KM_ANTES = 500;
const DIAS_ENTRE_AVISOS_KM = 30;
const hoje = new Date().toLocaleDateString('sv-SE', { timeZone: 'America/Sao_Paulo' });
const ehData = (v) => /^\d{4}-\d{2}-\d{2}/.test(String(v || ''));
const dia = (v) => { const [a, m, d] = String(v).slice(0, 10).split('-').map(Number); return Date.UTC(a, m - 1, d) / 86400000; };
const temNumero = (v) => String(v ?? '').trim() !== '' && Number.isFinite(Number(v));
const saida = [];
for (const item of $input.all()) {
  const c = item.json;
  if (String(c.optout).toLowerCase() === 'sim' || !c.telefone) continue;
  const avisado = ehData(c.ultimo_aviso) ? dia(c.ultimo_aviso) : null;
  if (avisado === dia(hoje)) continue;
  const dias = ehData(c.proxima_revisao) ? dia(c.proxima_revisao) - dia(hoje) : null;
  const porData = dias !== null && dias >= 0 && dias <= DIAS_ANTES
    && (avisado === null || avisado < dia(c.proxima_revisao) - DIAS_ANTES);
  const kmFalta = temNumero(c.km_proxima_revisao) && temNumero(c.km_atual)
    ? Number(c.km_proxima_revisao) - Number(c.km_atual) : null;
  const porKm = kmFalta !== null && kmFalta >= 0 && kmFalta <= KM_ANTES
    && (avisado === null || dia(hoje) - avisado >= DIAS_ENTRE_AVISOS_KM);
  const aniversario = ehData(c.nascimento) && String(c.nascimento).slice(5, 10) === hoje.slice(5, 10);
  if (porData || porKm) saida.push({ json: { ...c, motivo: 'revisao' } });
  else if (aniversario) saida.push({ json: { ...c, motivo: 'aniversario' } });
}
return saida.slice(0, LIMITE_DIARIO);
